#include <iostream>
#include <vector>
#include <queue>
#include <algorithm>
using namespace std;

const int INF = 1000000000;
const int HORIZON = 16;

int N, L, E;
vector<vector<int>> adj;
vector<bool> isGw;
vector<int> gws;

int gwDegOf(int u)
{
    int c = 0;
    for (int w : adj[u]) if (isGw[w]) c++;
    return c;
}

void eraseEdge(int a, int b)
{
    adj[a].erase(remove(adj[a].begin(), adj[a].end(), b), adj[a].end());
    adj[b].erase(remove(adj[b].begin(), adj[b].end(), a), adj[b].end());
}

void addEdge(int a, int b)
{
    // 避免重複加入（同一條邊可能被剪/還原兩次）
    if (find(adj[a].begin(), adj[a].end(), b) == adj[a].end()) adj[a].push_back(b);
    if (find(adj[b].begin(), adj[b].end(), a) == adj[b].end()) adj[b].push_back(a);
}

// 從 src 做 BFS（gateway 當障礙，除了 allowGw）
vector<int> bfsDist(int src, int allowGw)
{
    vector<int> d(N, -1);
    queue<int> q;
    q.push(src);
    d[src] = 0;
    while (!q.empty())
    {
        int u = q.front();
        q.pop();
        for (int v : adj[u])
        {
            if (isGw[v] && v != allowGw) continue;
            if (d[v] == -1) { d[v] = d[u] + 1; q.push(v); }
        }
    }
    return d;
}

// 模擬 agent 走一步；回傳新位置，-1 表示到不了任何 gateway（我們贏）
int agentStep(int agent, int target)
{
    // 旁邊有 gateway 就直接進去
    int gmin = -1;
    for (int w : adj[agent]) if (isGw[w] && (gmin == -1 || w < gmin)) gmin = w;
    if (gmin != -1) return gmin;

    vector<int> d = bfsDist(target, target);
    if (agent < (int)d.size() && d[agent] == -1)
    {
        int best = -1, bd = INF;
        for (size_t i = 0; i < gws.size(); i++)
        {
            vector<int> dd = bfsDist(gws[i], gws[i]);
            if (dd[agent] != -1 && dd[agent] < bd) { bd = dd[agent]; best = gws[i]; }
        }
        if (best == -1) return -1;
        d = bfsDist(best, best);
    }

    int bestW = -1;
    for (int w : adj[agent])
    {
        if (isGw[w]) continue;
        if (d[w] != -1 && d[w] == d[agent] - 1)
            if (bestW == -1 || w < bestW) bestW = w;
    }
    return bestW;
}

// 簡化策略：旁邊有 gateway 剪它，否則剪最靠近 agent 的 gateway 連結
pair<int, int> policyCut(int agent)
{
    int gmin = -1;
    for (int w : adj[agent]) if (isGw[w] && (gmin == -1 || w < gmin)) gmin = w;
    if (gmin != -1) return make_pair(agent, gmin);

    vector<int> d = bfsDist(agent, -1);
    int bu = -1, bg = -1, bd = INF;
    for (size_t i = 0; i < gws.size(); i++)
    {
        int g = gws[i];
        for (int u : adj[g])
        {
            if (d[u] == -1) continue;
            if (d[u] < bd) { bd = d[u]; bu = u; bg = g; }
        }
    }
    return make_pair(bu, bg);
}

// 模擬：先剪 (cu,cg)，之後用 policy 跑 HORIZON 回合；回傳存活回合數
int simulate(int agent, int target, int cu, int cg)
{
    vector<pair<int, int>> cuts;
    eraseEdge(cu, cg);
    cuts.push_back(make_pair(cu, cg));

    int survived = HORIZON;
    for (int t = 0; t < HORIZON; t++)
    {
        int nxt = agentStep(agent, target);
        if (nxt == -1) { survived = HORIZON + 1; break; }
        if (isGw[nxt]) { survived = t; break; }
        agent = nxt;

        pair<int, int> c = policyCut(agent);
        if (c.first == -1) { survived = HORIZON + 1; break; }
        eraseEdge(c.first, c.second);
        cuts.push_back(c);
    }

    for (size_t i = 0; i < cuts.size(); i++) addEdge(cuts[i].first, cuts[i].second);
    return survived;
}

int main()
{
    cin >> N >> L >> E;

    adj.assign(N, vector<int>());
    isGw.assign(N, false);

    for (int i = 0; i < L; i++)
    {
        int a, b;
        cin >> a >> b;
        adj[a].push_back(b);
        adj[b].push_back(a);
    }
    for (int i = 0; i < E; i++)
    {
        int g;
        cin >> g;
        isGw[g] = true;
        gws.push_back(g);
    }

    vector<char> cand(E, 1);
    int prev = -1;
    int target = gws.empty() ? -1 : gws[0];

    while (true)
    {
        int SI;
        if (!(cin >> SI)) break;

        // 用 agent 的移動推測目標
        if (prev != -1)
        {
            bool any = false;
            for (int i = 0; i < E; i++)
            {
                if (!cand[i]) continue;
                vector<int> d = bfsDist(gws[i], gws[i]);
                if (d[prev] != -1 && d[SI] != -1 && d[SI] < d[prev]) any = true;
                else cand[i] = 0;
            }
            if (!any) for (int i = 0; i < E; i++) cand[i] = 1;
        }
        // 取最近且仍可能是目標的 gateway 當模擬目標
        {
            vector<int> d = bfsDist(SI, -1);
            int bd = INF;
            for (int i = 0; i < E; i++)
            {
                if (!cand[i]) continue;
                vector<int> dd = bfsDist(gws[i], gws[i]);
                if (dd[SI] != -1 && dd[SI] < bd) { bd = dd[SI]; target = gws[i]; }
            }
        }

        // 候選剪法：agent 附近（距離 ≤ 5）的 gateway 連結
        vector<int> dist = bfsDist(SI, -1);
        vector<pair<int, int>> cands;
        for (size_t i = 0; i < gws.size(); i++)
        {
            int g = gws[i];
            for (int u : adj[g])
            {
                if (u == SI) { cands.push_back(make_pair(u, g)); continue; }
                if (dist[u] != -1 && dist[u] <= 7) cands.push_back(make_pair(u, g));
            }
        }
        if (cands.empty())
        {
            for (size_t i = 0; i < gws.size(); i++)
                for (int u : adj[gws[i]]) { cands.push_back(make_pair(u, gws[i])); break; }
        }

        // 候選目標很多（>4）時，對最近的 4 個取最壞情況，避免猜錯目標
        vector<int> targets;
        {
            vector<pair<int, int>> tv;
            for (int i = 0; i < E; i++)
            {
                if (!cand[i]) continue;
                vector<int> dd = bfsDist(gws[i], gws[i]);
                if (dd[SI] != -1) tv.push_back(make_pair(dd[SI], gws[i]));
            }
            sort(tv.begin(), tv.end());
            int lim = (tv.size() > 4) ? 4 : 1;
            for (size_t i = 0; i < tv.size() && (int)i < lim; i++) targets.push_back(tv[i].second);
        }
        if (targets.empty()) targets.push_back(target);

        int bestScore = -1, bu = -1, bg = -1;
        for (size_t i = 0; i < cands.size(); i++)
        {
            int worst = INF;
            for (size_t k = 0; k < targets.size(); k++)
            {
                int sc = simulate(SI, targets[k], cands[i].first, cands[i].second);
                if (sc < worst) worst = sc;
            }
            if (worst > bestScore)
            {
                bestScore = worst;
                bu = cands[i].first;
                bg = cands[i].second;
            }
        }
        if (bu == -1) break;

        cout << bu << " " << bg << endl;
        eraseEdge(bu, bg);
        prev = SI;
    }
    return 0;
}
